static int socket_pair(SOCKET *client,SOCKET *server){SOCKET listener;struct sockaddr_in address;int size;*client=*server=INVALID_SOCKET;listener=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(listener==INVALID_SOCKET)return 0;memset(&address,0,sizeof(address));address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(listener,(struct sockaddr*)&address,sizeof(address))||listen(listener,1)){closesocket(listener);return 0;}size=sizeof(address);if(getsockname(listener,(struct sockaddr*)&address,&size)){closesocket(listener);return 0;}*client=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(*client==INVALID_SOCKET||connect(*client,(struct sockaddr*)&address,sizeof(address))){closesocket(listener);return 0;}*server=accept(listener,NULL,NULL);closesocket(listener);return *server!=INVALID_SOCKET;}
static void runtime_options(PST_RUNTIME_OPTIONS *o,pst_u32 selection,const char *id){memset(o,0,sizeof(*o));o->struct_size=sizeof(*o);o->api_version=PST_API_VERSION;o->selection=selection;o->exact_backend_id=id;}
